<template><div class="app-container"><el-form :inline="true" size="small" :model="query"><el-form-item label="商品名称"><el-input v-model="query.productName" clearable @keyup.enter.native="load"/></el-form-item><el-form-item label="发布状态"><el-select v-model="query.publishStatus" clearable><el-option label="未上架" value="0"/><el-option label="已上架" value="1"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="load">查询</el-button></el-form-item></el-form><el-row class="mb8"><el-button type="primary" plain icon="el-icon-plus" size="mini" @click="openAdd" v-hasPermi="['mall:product:add']">新增商品</el-button><right-toolbar :showSearch.sync="showSearch" @queryTable="load"/></el-row><el-table v-loading="loading" :data="list"><el-table-column prop="spuId" label="SPU ID" width="85"/><el-table-column prop="spuCode" label="SPU 编码" width="130"/><el-table-column prop="productName" label="商品名称" min-width="180"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="brandName" label="品牌"/><el-table-column label="价格区间" width="130"><template slot-scope="s">¥{{ s.row.priceMin }} - ¥{{ s.row.priceMax }}</template></el-table-column><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.publishStatus === '1' ? 'success' : 'info'">{{ s.row.publishStatus === '1' ? '已上架' : '未上架' }}</el-tag></template></el-table-column><el-table-column label="操作" width="240"><template slot-scope="s"><el-button type="text" size="mini" icon="el-icon-edit" @click="openEdit(s.row)" v-hasPermi="['mall:product:edit']">修改</el-button><el-button type="text" size="mini" :icon="s.row.publishStatus === '1' ? 'el-icon-bottom' : 'el-icon-top'" @click="togglePublish(s.row)" v-hasPermi="['mall:product:publish']">{{ s.row.publishStatus === '1' ? '下架' : '上架' }}</el-button><el-button type="text" size="mini" icon="el-icon-delete" @click="remove(s.row)" v-hasPermi="['mall:product:remove']">删除</el-button></template></el-table-column></el-table><pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/><el-dialog :title="title" :visible.sync="dialog" width="700px"><el-form :model="form" label-width="90px"><el-row><el-col :span="12"><el-form-item label="商品名称"><el-input v-model="form.productName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="SPU 编码"><el-input v-model="form.spuCode"/></el-form-item></el-col></el-row><el-row><el-col :span="12"><el-form-item label="分类 ID"><el-input-number v-model="form.categoryId" :min="1"/></el-form-item></el-col><el-col :span="12"><el-form-item label="品牌 ID"><el-input-number v-model="form.brandId" :min="1"/></el-form-item></el-col></el-row><el-form-item label="副标题"><el-input v-model="form.subtitle"/></el-form-item><el-form-item label="主图地址"><el-input v-model="form.mainImage"/></el-form-item><el-form-item label="SKU 列表"><div v-for="(sku, i) in form.skuList" :key="i" class="sku-row"><el-input v-model="sku.skuCode" placeholder="SKU 编码"/><el-input v-model="sku.skuName" placeholder="SKU 名称"/><el-input-number v-model="sku.price" :min="0" :precision="2" placeholder="售价"/><el-input-number v-model="sku.availableStock" :min="0" placeholder="库存"/><el-button type="text" icon="el-icon-delete" @click="form.skuList.splice(i, 1)"/></div><el-button size="mini" icon="el-icon-plus" @click="form.skuList.push({ status: '1', availableStock: 0 })">添加 SKU</el-button></el-form-item></el-form><div slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></div></el-dialog></div></template>
<script>import { listProducts, getProduct, addProduct, updateProduct, publishProduct, delProduct } from '@/api/mall/catalog'
export default { name: 'MallProduct', data () { return { showSearch: true, loading: false, list: [], total: 0, query: { pageNum: 1, pageSize: 10 }, dialog: false, title: '', form: { skuList: [] } } }, created () { this.load() }, methods: { load () { this.loading = true; listProducts(this.query).then(r => { const d = r.data || r; this.list = d.rows || (Array.isArray(d) ? d : []); this.total = d.total || this.list.length }).finally(() => { this.loading = false }) }, openAdd () { this.title = '新增商品'; this.form = { publishStatus: '0', sortNo: 0, skuList: [{ status: '1', availableStock: 0 }] }; this.dialog = true }, openEdit (r) { getProduct(r.spuId).then(x => { this.title = '修改商品'; this.form = x.data || x; this.form.skuList = this.form.skuList || []; this.dialog = true }) }, save () { if (!this.form.productName || !this.form.spuCode || !this.form.categoryId || !this.form.skuList.length) return this.$modal.msgError('请完整填写商品和 SKU 信息'); (this.form.spuId ? updateProduct : addProduct)(this.form).then(() => { this.$modal.msgSuccess('保存成功'); this.dialog = false; this.load() }) }, togglePublish (r) { const status = r.publishStatus === '1' ? '0' : '1'; publishProduct(r.spuId, status).then(() => { this.$modal.msgSuccess('状态已更新'); this.load() }) }, remove (r) { this.$modal.confirm('确认删除该商品？').then(() => delProduct(r.spuId)).then(() => { this.$modal.msgSuccess('删除成功'); this.load() }).catch(() => {}) } } }</script>
